import {PRESETS,SCALE,NAMES,DRUMS,makeProject,validateProject,clone,snap,noteName,parseChain,clamp,drumVelocity,drumStatus,drumSound,drumName,writeMidiStep,nextMidiStep} from './model.js';
import {Engine} from './audio.js';
import {MidiKeyboard} from './midi.js';
import {copyPart,canPastePart,canPasteSound,pastePart} from './parts.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const TITLES=['PULSE','DRIFT','SHIMMER','UNDERTOW','DRUM','BASS'];const STORAGE='drew-circuit16-v1';
let project=makeProject(),mode='pitch',target=0,playing=false,busy=false,clipboard=null,queued=null,undo=[],redo=[],editGroup='',lastEdit=0,saveTimer,updateTimer,toastTimer,presets=[],lastPositions=[-1,-1,-1,-1,-1,-1],lastBeat=0,recordTimer,exportURL=null;
try{const stored=localStorage.getItem(STORAGE);if(stored)project=validateProject(JSON.parse(stored));}catch(e){console.warn('Autosave could not be restored',e);}
const engine=new Engine(onAudioEvent);
let midiArmed=false,midiStep=0,midiConnected=false,midiConnecting=false;
let partTarget='track:0',partClipboard=null;
const midi=new MidiKeyboard({onNote:enterMidiNote,onState:renderMidiDevices,onDisconnect:()=>{midiArmed=false;updateMidiUI();}});
const getPath=(o,path)=>path?path.split('.').reduce((x,k)=>x[k],o):o;
const setPath=(o,path,value)=>{const parts=path.split('.'),k=parts.pop();getPath(o,parts.join('.'))[k]=value;};
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600);}
function remember(group='action'){const now=performance.now();if(group==='action'||group!==editGroup||now-lastEdit>700){undo.push(clone(project));if(undo.length>40)undo.shift();redo=[];}editGroup=group;lastEdit=now;historyButtons();}
function historyButtons(){$('#undo').disabled=!undo.length;$('#redo').disabled=!redo.length;}
function scheduleSave(){clearTimeout(saveTimer);$('#saveStatus').textContent='Saving…';saveTimer=setTimeout(()=>{try{localStorage.setItem(STORAGE,JSON.stringify(project));$('#saveStatus').textContent='Saved in this browser';}catch{$('#saveStatus').textContent='Use SAVE to keep this project';}},400);}
function sync(){updateDrumStatus();updatePartUI();scheduleSave();clearTimeout(updateTimer);updateTimer=setTimeout(()=>engine.update(project),22);}
function currentTrack(ch=target){return ch===5?project.patterns[project.activePattern].bass:project.patterns[project.activePattern].tracks[ch];}
function trackPath(ch){return `patterns.${project.activePattern}.${ch===5?'bass':`tracks.${ch}`}`;}
function selection(options,value){return options.map(([v,n])=>`<option value="${escape(v)}" ${String(v)===String(value)?'selected':''}>${escape(n)}</option>`).join('');}
function soundOptions(value,drum=false){const list=presets.filter(p=>!!p.drum===drum);return list.map(p=>`<option value="${p.bank}:${p.program}" ${`${p.bank}:${p.program}`===value?'selected':''}>${escape(p.name)}${p.bank?` · ${p.bank}`:''}</option>`).join('');}
function ms(ch){const m=project.mix[ch];return `<div class="ms"><button class="toggle ${m.mute?'on':''}" data-mix="${ch}" data-mix-action="mute" aria-label="Mute ${TITLES[ch]}" aria-pressed="${m.mute}">M</button><button class="toggle ${m.solo?'on':''}" data-mix="${ch}" data-mix-action="solo" aria-label="Solo ${TITLES[ch]}" aria-pressed="${m.solo}">S</button></div>`;}
function knob(label,path,min,max,step,format='percent'){const val=getPath(project,path),frac=(val-min)/(max-min);return `<div class="knob-control"><div class="knob-wrap" style="--angle:${-135+frac*270}deg"><div class="knob-face"></div><input type="range" min="${min}" max="${max}" step="${step}" value="${val}" data-path="${path}" data-format="${format}" aria-label="${label}" title="${label}: drag left or right, or use arrow keys"></div><label>${label}</label><output>${formatValue(val,format)}</output></div>`;}
function formatValue(v,f){if(f==='hz')return v>=1000?`${(v/1000).toFixed(1)}k Hz`:`${Math.round(v)} Hz`;if(f==='seconds')return `${v.toFixed(2)} s`;if(f==='number')return v.toFixed(1);return `${Math.round(v*100)}%`;}
const rates=[[.125,'1/32'],[.25,'1/16'],[.5,'1/8'],[1,'1/4'],[2,'1/2'],[4,'1 bar']];
function settings(ch){const t=currentTrack(ch),p=trackPath(ch);return `<div class="seq-settings"><label>LENGTH<select data-path="${p}.length" aria-label="${TITLES[ch]} sequence length">${selection(Array.from({length:16},(_,i)=>[i+1,i+1]),t.length)}</select></label><label>RATE<select data-path="${p}.rate" aria-label="${TITLES[ch]} clock rate">${selection(rates,t.rate)}</select></label><label>DIRECTION<select data-path="${p}.direction" aria-label="${TITLES[ch]} direction">${selection([['forward','Forward'],['reverse','Reverse'],['pendulum','Pendulum']],t.direction)}</select></label><label>OCTAVE<select data-path="${p}.octave" aria-label="${TITLES[ch]} octave">${selection([[-2,'−2'],[-1,'−1'],[0,'0'],[1,'+1'],[2,'+2']],t.octave)}</select></label><label>VOICE<select data-path="${p}.chord" aria-label="${TITLES[ch]} chord">${selection([['single','Single'],['fifth','Fifth'],['minor','Minor'],['major','Major'],['sus','Sus 4']],t.chord)}</select></label><label>EDIT<button class="small" data-target="${ch}" title="Select ${TITLES[ch]} for editing">${target===ch?'SELECTED':'SELECT'}</button></label></div>`;}
function stepInfo(t,i){if(mode==='velocity')return {min:1,max:127,step:1,value:t.velocity[i],label:String(t.velocity[i]),key:'velocity',factor:1};if(mode==='gate')return {min:5,max:195,step:1,value:Math.round(t.gates[i]*100),label:`${Math.round(t.gates[i]*100)}%`,key:'gates',factor:.01};if(mode==='chance')return {min:0,max:100,step:1,value:Math.round(t.chance[i]*100),label:`${Math.round(t.chance[i]*100)}%`,key:'chance',factor:.01};if(mode==='repeat')return {min:1,max:4,step:1,value:t.ratchet[i],label:`×${t.ratchet[i]}`,key:'ratchet',factor:1};return {min:0,max:127,step:1,value:t.notes[i],label:noteName(snap(t.notes[i],project.root,project.scale)+t.octave*12),key:'notes',factor:1};}
function steps(ch){const t=currentTrack(ch);return `<div class="step-grid" data-grid="${ch}">${Array.from({length:16},(_,i)=>{const s=stepInfo(t,i);return `<div class="step ${i>=t.length?'inactive':''}" data-step="${i}"><button class="value" data-preview="${ch}" data-index="${i}" title="Audition ${TITLES[ch]} step ${i+1}">${s.label}</button><input class="vertical" type="range" min="${s.min}" max="${s.max}" step="${s.step}" value="${s.value}" data-step-ch="${ch}" data-index="${i}" data-step-key="${s.key}" data-factor="${s.factor}" aria-label="${TITLES[ch]} step ${i+1} ${mode}"><button class="step-index midi-step-select" data-midi-step="${i}" data-midi-ch="${ch}" aria-label="Select ${TITLES[ch]} step ${i+1} for MIDI" title="Select this step for MIDI entry">${i+1}</button><button class="gate ${t.on[i]?'on':''} ${t.tie[i]?'tie':''}" data-gate="${ch}" data-index="${i}" aria-label="${TITLES[ch]} step ${i+1}${t.tie[i]?' tied':''}" aria-pressed="${t.on[i]}" title="Step ${i+1}: click to toggle · Shift-click to tie"></button></div>`;}).join('')}</div>`;}
function renderSequences(){$('#sequences').innerHTML=Array.from({length:4},(_,ch)=>{const t=currentTrack(ch);return `<section class="panel sequence ${target===ch?'selected':''}" data-seq="${ch}" aria-label="${TITLES[ch]} sequencer"><div class="seq-meta"><div class="row-title"><span class="track-num">0${ch+1}</span><h2>${TITLES[ch]}</h2>${ms(ch)}</div><select class="patch-select" data-sound="${ch}" aria-label="${TITLES[ch]} soundfont instrument">${soundOptions(`${t.bank}:${t.program}`)}</select>${settings(ch)}</div>${steps(ch)}</section>`;}).join('');}
function renderBass(){const t=currentTrack(5),path=trackPath(5);$('#bass').innerHTML=`<div class="bass-heading"><h2>BASS MACHINE</h2>${ms(5)}</div><div class="bass-options"><select data-path="${path}.source" aria-label="Bass sound source">${selection([['analog','Analog oscillator'],['soundfont','GeneralUser GS']],t.source)}</select>${t.source==='analog'?`<select data-path="${path}.wave" aria-label="Bass oscillator waveform">${selection([['triangle','Triangle'],['saw','Sawtooth'],['sine','Sine']],t.wave)}</select>`:`<select data-sound="5" aria-label="Bass soundfont instrument">${soundOptions(`${t.bank}:${t.program}`)}</select>`}<select data-path="${path}.length" aria-label="Bass sequence length">${selection(Array.from({length:16},(_,i)=>[i+1,`${i+1} steps`]),t.length)}</select><select data-path="${path}.rate" aria-label="Bass clock rate">${selection(rates.map(([v,n])=>[v,`${n} rate`]),t.rate)}</select></div>${steps(5)}<div class="bass-knobs">${knob('CUTOFF',`${path}.cutoff`,80,10000,10,'hz')}${knob('DECAY',`${path}.decay`,.08,3,.01,'seconds')}${knob('SLIDE',`${path}.slide`,0,1,.01)}${knob('ACCENT',`${path}.accent`,0,1,.01)}</div>`;}
function updateDrumStatus(){const el=$('#drumStatus');if(!el)return;const issue=drumStatus(project);el.textContent=issue||unmappedDrumStatus()||'Choose a sound for each row · ▶ auditions · Key numbers use C4 = 60';el.classList.toggle('warning',!!(issue||unmappedDrumStatus()));$$('[data-path="mix.4.volume"]').forEach(el=>el.value=project.mix[4].volume);$('#drumLevelValue').textContent=Math.round(project.mix[4].volume*100)+'%';}
function unmappedDrumStatus(){const d=project.patterns[project.activePattern].drums;const rows=d.lanes.map((l,i)=>!drumSound(d.kit,l.note)?i+1:null).filter(Boolean);return rows.length?`No sample on the selected key in row${rows.length>1?'s':''} ${rows.join(', ')}. Choose another key or kit.`:'';}
function drumNoteOptions(kit,note){const options=Array.from({length:128},(_,n)=>`<option value="${n}" ${n===note?'selected':''}>${n} · ${noteName(n)} — ${escape(drumSound(kit,n)?.name||'No sample')}</option>`);return '<optgroup label="Sounds in this kit">'+options.filter((_,n)=>drumSound(kit,n)).join('')+'</optgroup><optgroup label="Other keys — no sample in this kit">'+options.filter((_,n)=>!drumSound(kit,n)).join('')+'</optgroup>';}
async function previewDrum(index){const lane=project.patterns[project.activePattern].drums.lanes[index],issue=drumStatus(project);if(project.master===0||project.mix[4].mute||project.mix[4].volume===0||(project.mix.some(m=>m.solo)&&!project.mix[4].solo)){toast(issue);return;}if(lane.volume===0){toast(`${lane.name} level is at zero — raise its row slider.`);return;}if(!drumSound(project.patterns[project.activePattern].drums.kit,lane.note)){toast('This key has no sample in the selected kit. Choose another key or kit.');return;}if(busy)return;busy=true;updateTransport();try{if(!engine.ready)$('#audioStatus').textContent='Loading GeneralUser GS…';await engine.init(project);engine.update(project);engine.preview(4,lane.note,'soundfont',drumVelocity(lane.volume));$('#audioStatus').textContent='GeneralUser GS · 269 presets';}catch(e){toast(e.message);$('#audioStatus').textContent='Could not load audio — press Play to retry';}finally{busy=false;updateTransport();}}
function renderDrums(){const d=project.patterns[project.activePattern].drums,path=`patterns.${project.activePattern}.drums`;$('#drums').innerHTML=`<div class="drum-heading"><h2>PERCUSSION</h2>${ms(4)}<label class="drum-level">LEVEL <input type="range" min="0" max="1" step=".01" data-path="mix.4.volume" value="${project.mix[4].volume}" aria-label="Drum machine level"><output id="drumLevelValue"></output></label><select data-drum-kit aria-label="Drum kit">${soundOptions(`0:${d.kit}`,true)}</select><label class="compact-label">LENGTH<select data-path="${path}.length" aria-label="Drum sequence length">${selection(Array.from({length:16},(_,i)=>[i+1,i+1]),d.length)}</select></label><label class="compact-label">RATE<select data-path="${path}.rate" aria-label="Drum clock rate">${selection(rates,d.rate)}</select></label></div><div class="drum-grid"><div class="drum-counts">${Array.from({length:16},(_,i)=>`<span>${i+1}</span>`).join('')}</div>${d.lanes.map((l,j)=>{const name=drumName(d.kit,l.note),row=`--lane:${j};--row:${j+2}`;return `<div class="drum-lane-control" style="${row}"><button class="drum-preview" data-drum-preview="${j}" aria-label="Audition row ${j+1}: ${escape(name)}" title="Play ${escape(name)}">▶</button><select data-drum-note="${j}" aria-label="Drum row ${j+1} sound" title="${escape(name)} · MIDI ${l.note}">${drumNoteOptions(d.kit,l.note)}</select></div><div class="drum-steps" style="${row}" data-drum-lane="${j}">${l.on.map((on,i)=>`<button class="gate ${on?'on':''}" style="${i>=d.length?'opacity:.3':''}" data-drum="${j}" data-index="${i}" aria-label="Row ${j+1} ${escape(name)} step ${i+1}" aria-pressed="${on}"></button>`).join('')}</div><input class="drum-vol" style="${row}" type="range" min="0" max="1" step=".01" value="${l.volume}" data-path="${path}.lanes.${j}.volume" aria-label="Drum row ${j+1} ${escape(name)} level">`;}).join('')}</div><p id="drumStatus" class="drum-status" role="status"></p>`;updateDrumStatus();lastPositions[4]=-1;}

function renderFX(){$('#fx').innerHTML=knob('FILTER','fx.cutoff',120,18000,10,'hz')+knob('RESONANCE','fx.resonance',.1,8,.1,'number')+knob('MOTION','fx.motion',0,1,.01)+knob('DELAY','fx.delay',0,.8,.01)+knob('FEEDBACK','fx.feedback',0,.8,.01)+knob('REVERB','fx.reverb',0,.8,.01);$('#motionControls').innerHTML=knob('SWING','swing',0,.45,.01)+knob('EVOLVE','evolution',0,.5,.01);$('#echoRate').value=project.fx.delayBeats;}
function renderMixer(){$('#mixer').innerHTML=project.mix.map((m,ch)=>`<div class="mix-channel"><label>${ch<4?ch+1:ch===4?'DRUM':'BASS'}</label><input class="vertical" type="range" min="0" max="1" step=".01" value="${m.volume}" data-path="mix.${ch}.volume" aria-label="${TITLES[ch]} volume">${ms(ch)}<input class="mix-pan" type="range" min="-1" max="1" step=".01" value="${m.pan}" data-path="mix.${ch}.pan" aria-label="${TITLES[ch]} pan" title="Pan: left / right"></div>`).join('');$('[data-path="master"]').value=project.master;$('#masterValue').textContent=Math.round(project.master*100)+'%';}
function renderPatterns(){$('#patterns').innerHTML=project.patterns.map((p,i)=>`<button data-pattern="${i}" class="${i===project.activePattern?'active':''} ${queued===i?'queued':''}" aria-label="Pattern ${String.fromCharCode(65+i)}" aria-pressed="${i===project.activePattern}">${String.fromCharCode(65+i)}</button>`).join('');$('#song').textContent=project.songMode?'CHAIN ON':'CHAIN OFF';$('#song').classList.toggle('active',project.songMode);$('#song').setAttribute('aria-pressed',project.songMode);$('#chain').value=project.chain;}
function renderTabs(){$('#editorTabs').innerHTML=[['pitch','PITCH'],['velocity','VELOCITY'],['gate','GATE'],['chance','CHANCE'],['repeat','REPEAT']].map(([k,n])=>`<button data-mode="${k}" class="${mode===k?'active':''}" aria-pressed="${mode===k}">${n}</button>`).join('');$('#editTarget').value=target;}
function renderAll(){const scroll=window.scrollY;renderSequences();renderBass();renderDrums();renderFX();renderMixer();renderPatterns();renderTabs();updateMidiUI();updatePartUI();$('#tempo').value=project.tempo;$('#root').value=project.root;$('#scale').value=project.scale;$('#preset').value=PRESETS.findIndex(p=>p.name===project.title);historyButtons();lastPositions.fill(-1);window.scrollTo({top:scroll,behavior:'instant'});}
function renderTrackSteps(){renderSequences();renderBass();lastPositions.fill(-1);updateMidiUI();updatePartUI();}
function chooseTarget(ch){target=Number(ch);partTarget=target===5?'bass':`track:${target}`;updatePartUI();$('#editTarget').value=target;$$('.sequence').forEach(el=>el.classList.toggle('selected',Number(el.dataset.seq)===target));$$('[data-target]').forEach(el=>el.textContent=Number(el.dataset.target)===target?'SELECTED':'SELECT');updateMidiUI();}
function updatePattern(index){project.activePattern=index;queued=null;renderPatterns();renderSequences();renderDrums();renderBass();engine.update(project);scheduleSave();lastPositions.fill(-1);updateMidiUI();updatePartUI();}
function onAudioEvent(d){if(d.type==='position'){lastBeat=d.beat;for(let ch=0;ch<6;ch++){const n=d.positions[ch];if(lastPositions[ch]===n)continue;if(ch===4){$$('.drum-steps .playing').forEach(el=>el.classList.remove('playing'));if(n>=0)$$(`.drum-steps [data-index="${n}"]`).forEach(el=>el.classList.add('playing'));}else{const grid=$(`[data-grid="${ch}"]`);grid?.querySelector('.playing')?.classList.remove('playing');if(n>=0)grid?.children[n]?.classList.add('playing');}lastPositions[ch]=n;}$('#barCounter').textContent=`BAR ${String(Math.floor(d.beat/4)+1).padStart(3,'0')} · ${Math.floor(d.beat%4)+1}`;}else if(d.type==='pattern'){updatePattern(d.index);}else if(d.type==='error'){toast(d.message);$('#audioStatus').textContent='Audio error — reload to restart';playing=false;updateTransport();}else if(d.type==='context'&&d.state==='suspended'&&playing){playing=false;engine.stop();updateTransport();toast('Audio paused by the browser. Press Play to resume.');}}
function updateTransport(){$('#play').classList.toggle('active',playing);$('#play').innerHTML=playing?'<span>▶</span> PLAYING':'<span>▶</span> PLAY';$('#audioLED').classList.toggle('on',engine.ready);$('#play').disabled=busy;}
async function play(){if(busy)return;if(playing){stop();return;}busy=true;$('#audioStatus').textContent=engine.ready?'Starting…':'Loading GeneralUser GS…';updateTransport();try{if(project.songMode)project.activePattern=parseChain(project.chain)[0].pattern;await engine.start(project);playing=true;renderAll();$('#audioStatus').textContent='GeneralUser GS · 269 presets';$('#hint').textContent='Click a step to toggle · Shift-click to tie · Move sliders to shape notes';}catch(e){toast(e.message);$('#audioStatus').textContent='Could not load audio — press Play to retry';}finally{busy=false;updateTransport();}}
function stop(){engine.stop();playing=false;queued=null;renderPatterns();lastBeat=0;$('#barCounter').textContent='BAR 001 · 1';$$('.playing').forEach(el=>{if(!el.classList.contains('hardware'))el.classList.remove('playing');});lastPositions.fill(-1);updateTransport();}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),120000);}
function fileName(ext){return `${project.title.replace(/[^\w -]/g,'').replace(/\s+/g,'-')||'Circuit-16'}-${ext}`;}
async function record(){if(busy)return;try{if(engine.recording){clearInterval(recordTimer);$('#record').disabled=true;const blob=await engine.stopRecording();download(blob,fileName('Live.wav'));$('#record').classList.remove('active');$('#record').innerHTML='<span>●</span> REC';$('#record').disabled=false;toast('Live recording saved as WAV.');}else{await engine.init(project);await engine.startRecording(project);if(!playing)await play();$('#record').classList.add('active');recordTimer=setInterval(()=>{const s=Math.floor((performance.now()-engine.recordStart)/1000);$('#record').innerHTML=`<span>●</span> ${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;if(s>=1800){record();toast('30-minute recording saved. Start a new recording to continue.');}},500);toast('Recording your live performance. Press REC again to save.');}}catch(e){toast(e.message);$('#record').disabled=false;}}
function restoreHistory(from,to){if(!from.length)return;const was=playing;to.push(clone(project));project=from.pop();queued=null;if(was){engine.stop();engine.start(project);}else engine.update(project);renderAll();sync();editGroup='';}
function mutateTrack(action){remember();const t=currentTrack();if(action==='left'||action==='right'){for(const key of ['notes','on','velocity','gates','chance','ratchet','tie']){const arr=t[key].slice(0,t.length);action==='left'?arr.push(arr.shift()):arr.unshift(arr.pop());t[key].splice(0,t.length,...arr);}}else if(action==='clear'){t.on.fill(false);t.tie.fill(false);}else if(action==='variation'){t.notes=t.notes.map((n,i)=>Math.random()<.23?snap(clamp(n+(Math.random()<.5?-2:3),0,127),project.root,project.scale):n);t.velocity=t.velocity.map(v=>Math.round(clamp(v+(Math.random()-.5)*14,35,117)));}renderTrackSteps();sync();}
function updateMidiUI(message){
 const t=currentTrack();midiStep=Math.max(0,Math.min(midiStep,t.length-1));
 $('#midiStep').innerHTML=selection(Array.from({length:t.length},(_,i)=>[i,`${String(i+1).padStart(2,'0')}`]),midiStep);
 $('#midiArm').disabled=!midiConnected;$('#midiArm').textContent=midiArmed?'STEP ENTRY ON':'STEP ENTRY OFF';$('#midiArm').classList.toggle('active',midiArmed);$('#midiArm').setAttribute('aria-pressed',midiArmed);
 $('#midiConnect').disabled=midiConnecting;$('#midiConnect').textContent=midiConnecting?'CONNECTING…':midi.access?'DISCONNECT':'CONNECT MIDI';
 $('#midiTarget').textContent=TITLES[target];
 $$('[data-grid] .step').forEach(el=>el.classList.toggle('midi-target',midiArmed&&Number(el.parentElement.dataset.grid)===target&&Number(el.dataset.step)===midiStep));
 $('#midiStatus').textContent=message||(midiConnected?(midiArmed?`Play one key to write ${TITLES[target]} step ${midiStep+1}. Follows KEY & SCALE; Chromatic accepts every note.`:'Choose a step, then turn STEP ENTRY on.'):midi.access?'No selected keyboard connected. Plug in a MIDI keyboard or choose another input.':'Connect a MIDI keyboard to enter pitches. Click a step number or note name to choose where to write.');
}
function renderMidiDevices({devices,selected,connected}){
 midiConnected=connected;
 $('#midiDevice').innerHTML=devices.length?devices.map(d=>`<option value="${escape(d.id)}" ${d.id===selected?'selected':''}>${escape(d.name||d.manufacturer||'MIDI input')}</option>`).join(''):'<option value="">No MIDI inputs</option>';
 if(!devices.some(d=>d.id===selected)&&selected){$('#midiDevice').insertAdjacentHTML('afterbegin','<option value="" selected>Keyboard disconnected</option>');}
 $('#midiDevice').disabled=!devices.length;updateMidiUI();
}
async function connectMidi(){
 if(midi.access){midi.disconnect();updateMidiUI('MIDI disconnected.');return;}
 if(midiConnecting)return;
 if(!navigator.requestMIDIAccess){updateMidiUI('MIDI is unavailable in this browser or preview. Open the HTTPS site in a browser with Web MIDI support.');return;}
 midiConnecting=true;updateMidiUI('Allow MIDI access when your browser asks.');
 // Start audio from this click so the first MIDI key can audition without starting playback.
 const audioReady=engine.init(project).then(()=>{$('#audioStatus').textContent='GeneralUser GS · 269 presets';updateTransport();}).catch(()=>{});
 try{await midi.connect(options=>navigator.requestMIDIAccess(options));}
 catch(e){midiArmed=false;updateMidiUI(e.name==='NotAllowedError'||e.name==='SecurityError'?'MIDI permission was blocked. Allow MIDI for this site and try CONNECT MIDI again in its own browser tab.':`Could not connect MIDI: ${e.message}`);}
 finally{midiConnecting=false;$('#midiConnect').disabled=false;$('#midiConnect').textContent=midi.access?'DISCONNECT':'CONNECT MIDI';}
}
function enterMidiNote({note,velocity}){
 if(!midiArmed||!midiConnected||document.hidden||document.querySelector('dialog[open]'))return;
 const t=currentTrack(),at=midiStep;
 remember();const played=writeMidiStep(project,target,at,note,velocity,$('#midiVelocity').checked);if(played===null)return;
 engine.update(project);if(!playing)engine.preview(target,played,t.source,$('#midiVelocity').checked?velocity:t.velocity[at]);
 midiStep=nextMidiStep(at,t.length,$('#midiAdvance').checked);renderTrackSteps();sync();
 updateMidiUI(`${noteName(played)} → ${TITLES[target]} step ${at+1}${$('#midiAdvance').checked?` · next ${midiStep+1}`:''}${!engine.ready?' · Press PLAY to enable sound':''}`);
}
$('#midiConnect').onclick=connectMidi;
$('#midiDevice').onchange=e=>{midiArmed=false;midi.select(e.target.value);updateMidiUI();};
$('#midiArm').onclick=()=>{if(!midiConnected)return;midiArmed=!midiArmed;if(midiArmed){mode='pitch';renderTabs();renderTrackSteps();}updateMidiUI();};
$('#midiStep').onchange=e=>{midiStep=Number(e.target.value);updateMidiUI();};


function partName(id,pattern=project.patterns[project.activePattern]){
 if(id==='drums')return 'All drums';
 if(id==='bass')return 'BASS';
 if(id.startsWith('row:')){const i=Number(id.slice(4));return `Drum row ${i+1} · ${drumName(pattern.drums.kit,pattern.drums.lanes[i].note)}`;}
 return TITLES[Number(id.slice(6))];
}
function updatePartUI(){
 const choices=[...Array.from({length:4},(_,i)=>`track:${i}`),'bass','drums',...Array.from({length:8},(_,i)=>`row:${i}`)];
 $('#partTarget').innerHTML=selection(choices.map(id=>[id,partName(id)]),partTarget);
 const compatible=canPastePart(partClipboard,partTarget),sound=canPasteSound(partClipboard,partTarget);
 $('#pastePart').disabled=!compatible;
 $('#includePartSound').disabled=!!partClipboard&&!sound;
 $('#includePartSound').parentElement.title=partClipboard&&!sound?'Melody and bass exchange notes and sequence settings while keeping their own sound engines.':'';
 $('#partDestination').textContent=`IN ${String.fromCharCode(65+project.activePattern)}`;
 let message='Choose a part, COPY PART, then choose its destination and PASTE PART. Includes all 16 steps and sequence timing.';
 if(partClipboard){
  message=`Copied ${partClipboard.label}. `;
  if(!compatible)message+=partClipboard.kind==='row'?'Choose a drum row to paste.':partClipboard.kind==='drums'?'Choose All drums to paste.':'Choose a melodic sequence or BASS to paste.';
  else{
   message+=`Paste into ${String.fromCharCode(65+project.activePattern)} · ${partName(partTarget)}. `;
   message+=$('#includePartSound').checked&&sound?(partTarget.startsWith('row:')?'Also copies key and row level; uses the destination kit.':'Includes sound settings.'):'Keeps the destination sound.';
   if(partTarget.startsWith('row:'))message+=' Row timing follows the destination drum machine.';
  }
 }
 $('#partStatus').textContent=message;
}
$('#partTarget').onchange=e=>{partTarget=e.target.value;if(partTarget==='bass'||partTarget.startsWith('track:'))chooseTarget(partTarget==='bass'?5:Number(partTarget.slice(6)));else updatePartUI();};
$('#includePartSound').onchange=updatePartUI;
$('#copyPart').onclick=()=>{
 partClipboard=copyPart(project.patterns[project.activePattern],partTarget);
 partClipboard.label=`${String.fromCharCode(65+project.activePattern)} · ${partName(partTarget)}`;
 updatePartUI();toast(`Copied ${partClipboard.label}.`);
};
$('#pastePart').onclick=()=>{
 if(!canPastePart(partClipboard,partTarget))return;
 remember();pastePart(project.patterns[project.activePattern],partTarget,partClipboard,$('#includePartSound').checked);
 renderAll();sync();toast(`Pasted into ${String.fromCharCode(65+project.activePattern)} · ${partName(partTarget)}. Undo is available.`);
};

$('#play').onclick=play;$('#stop').onclick=stop;$('#record').onclick=record;
$('#help').onclick=()=>$('#helpDialog').showModal();$('#export').onclick=()=>{$('#exportDialog').showModal();};$$('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close());
$('#fullscreen').onclick=async()=>{try{document.fullscreenElement?await document.exitFullscreen():await document.documentElement.requestFullscreen();}catch{toast('Open this studio in its own browser tab for full screen.');}};
$('#save').onclick=()=>{download(new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),fileName('Project.circuit16'));toast('Project downloaded.');};$('#load').onclick=()=>$('#fileInput').click();
$('#fileInput').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw Error('That file is too large to be a Circuit 16 project.');const p=validateProject(JSON.parse(await file.text()));remember();const was=playing;stop();project=p;renderAll();sync();if(was)await play();toast('Project loaded.');}catch(e){toast(e.message||'Could not open that project.');}finally{$('#fileInput').value='';}};
$('#undo').onclick=()=>restoreHistory(undo,redo);$('#redo').onclick=()=>restoreHistory(redo,undo);
$('#copy').onclick=()=>{clipboard=clone(project.patterns[project.activePattern]);$('#paste').disabled=false;toast(`Copied pattern ${String.fromCharCode(65+project.activePattern)}.`);};$('#paste').onclick=()=>{if(!clipboard)return;remember();project.patterns[project.activePattern]=clone(clipboard);renderAll();sync();toast('Pattern pasted.');};
$('#song').onclick=()=>{try{parseChain($('#chain').value);remember();project.chain=$('#chain').value.toUpperCase().trim();project.songMode=!project.songMode;renderPatterns();sync();toast(project.songMode?'Chain enabled. Press Stop and Play to start at its first pattern.':'Chain off. Current pattern will repeat.');}catch(e){toast(e.message);}};
$('#chain').onchange=()=>{try{parseChain($('#chain').value);remember();project.chain=$('#chain').value.toUpperCase().trim();sync();}catch(e){toast(e.message);$('#chain').value=project.chain;}};
$('#preset').onchange=async e=>{const index=Number(e.target.value);if(index<0)return;remember();const was=playing;stop();project=makeProject(index);renderAll();sync();if(was)await play();toast(PRESETS[index].detail);};
$('#tempo').onchange=e=>{remember();project.tempo=Math.round(clamp(e.target.value,30,240));e.target.value=project.tempo;sync();};
$('#root').onchange=e=>{remember();const root=Number(e.target.value),delta=root-project.root;for(const pat of project.patterns)for(const t of [...pat.tracks,pat.bass])t.notes=t.notes.map(n=>clamp(n+delta,0,127));project.root=root;renderTrackSteps();sync();};
$('#scale').onchange=e=>{remember();project.scale=e.target.value;renderTrackSteps();sync();};
$('#editTarget').onchange=e=>chooseTarget(e.target.value);$('#shiftLeft').onclick=()=>mutateTrack('left');$('#shiftRight').onclick=()=>mutateTrack('right');$('#variation').onclick=()=>mutateTrack('variation');$('#clear').onclick=()=>mutateTrack('clear');
$('#app').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.midiStep!==undefined){chooseTarget(Number(b.dataset.midiCh));midiStep=Number(b.dataset.midiStep);updateMidiUI();}if(b.dataset.mode){mode=b.dataset.mode;renderTabs();renderTrackSteps();}if(b.dataset.target!==undefined)chooseTarget(b.dataset.target);if(b.dataset.pattern!==undefined){const i=Number(b.dataset.pattern);if(playing){queued=i;engine.queue(i);renderPatterns();toast(`Pattern ${String.fromCharCode(65+i)} queued for the next bar.`);}else{remember();updatePattern(i);}}if(b.dataset.gate!==undefined){const ch=Number(b.dataset.gate),i=Number(b.dataset.index);remember();chooseTarget(ch);const t=currentTrack(ch);if(e.shiftKey){t.tie[i]=!t.tie[i];t.on[i]=true;}else t.on[i]=!t.on[i];b.classList.toggle('on',t.on[i]);b.classList.toggle('tie',t.tie[i]);b.setAttribute('aria-pressed',t.on[i]);sync();}if(b.dataset.drumPreview!==undefined){partTarget=`row:${b.dataset.drumPreview}`;updatePartUI();previewDrum(Number(b.dataset.drumPreview));}if(b.dataset.drum!==undefined){partTarget=`row:${b.dataset.drum}`;updatePartUI();remember();const j=Number(b.dataset.drum),i=Number(b.dataset.index),l=project.patterns[project.activePattern].drums.lanes[j];l.on[i]=!l.on[i];b.classList.toggle('on',l.on[i]);b.setAttribute('aria-pressed',l.on[i]);sync();if(l.on[i]&&!playing)previewDrum(j);}if(b.dataset.mix!==undefined){remember();const ch=Number(b.dataset.mix),key=b.dataset.mixAction;project.mix[ch][key]=!project.mix[ch][key];$$(`[data-mix="${ch}"][data-mix-action="${key}"]`).forEach(el=>{el.classList.toggle('on',project.mix[ch][key]);el.setAttribute('aria-pressed',project.mix[ch][key]);});sync();}if(b.dataset.preview!==undefined){const ch=Number(b.dataset.preview),i=Number(b.dataset.index),t=currentTrack(ch);chooseTarget(ch);midiStep=i;updateMidiUI();if(engine.ready)engine.preview(ch,snap(t.notes[i],project.root,project.scale)+t.octave*12,t.source);else toast('Press Play once to turn on the sound engine.');}});
$('#app').addEventListener('input',e=>{const el=e.target;if(el.dataset.stepCh!==undefined){const ch=Number(el.dataset.stepCh),i=Number(el.dataset.index),key=el.dataset.stepKey;remember(`step-${ch}-${i}-${key}`);chooseTarget(ch);midiStep=i;updateMidiUI();const t=currentTrack(ch);let v=Number(el.value)*Number(el.dataset.factor);if(key==='notes')v=snap(v,project.root,project.scale);t[key][i]=v;el.closest('.step').querySelector('.value').textContent=stepInfo(t,i).label;if(key==='notes'&&!playing)engine.preview(ch,v+t.octave*12,t.source);sync();}else if(el.matches('input[data-path]')){const path=el.dataset.path;remember(path);setPath(project,path,Number(el.value));if(el.dataset.format){el.parentElement.style.setProperty('--angle',`${-135+(Number(el.value)-Number(el.min))/(Number(el.max)-Number(el.min))*270}deg`);el.closest('.knob-control').querySelector('output').textContent=formatValue(Number(el.value),el.dataset.format);}if(path==='master')$('#masterValue').textContent=Math.round(project.master*100)+'%';sync();}});
$('#app').addEventListener('change',e=>{const el=e.target;if(el.matches('select[data-path]')){remember();const path=el.dataset.path,old=getPath(project,path);setPath(project,path,typeof old==='number'?Number(el.value):el.value);if(path.endsWith('.source'))renderBass();if(path.endsWith('.length')){const ch=path.includes('.bass')?5:path.includes('.tracks.')?Number(path.split('.')[3]):4;if(ch===4)renderDrums();else $$(`[data-grid="${ch}"] .step`).forEach((s,i)=>s.classList.toggle('inactive',i>=getPath(project,path)));}if(path.endsWith('.octave'))renderTrackSteps();updateMidiUI();sync();}else if(el.dataset.sound!==undefined){remember();const ch=Number(el.dataset.sound),t=currentTrack(ch),[bank,program]=el.value.split(':').map(Number);t.bank=bank;t.program=program;sync();}else if(el.dataset.drumNote!==undefined){partTarget=`row:${el.dataset.drumNote}`;remember();const j=Number(el.dataset.drumNote),d=project.patterns[project.activePattern].drums;d.lanes[j].note=Number(el.value);d.lanes[j].name=drumName(d.kit,d.lanes[j].note);renderDrums();sync();$('#drums select[data-drum-note="'+j+'"]').focus({preventScroll:true});}else if(el.hasAttribute('data-drum-kit')){partTarget='drums';remember();const d=project.patterns[project.activePattern].drums;d.kit=Number(el.value.split(':')[1]);d.lanes.forEach(l=>l.name=drumName(d.kit,l.note));renderDrums();sync();$('#drums select[data-drum-kit]').focus({preventScroll:true});}});
document.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||document.querySelector('dialog[open]'))return;if(e.code==='Space'){e.preventDefault();play();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?restoreHistory(redo,undo):restoreHistory(undo,redo);}});
window.addEventListener('beforeunload',e=>{if(engine.recording){e.preventDefault();e.returnValue='';}try{localStorage.setItem(STORAGE,JSON.stringify(project));}catch{}});
$('#renderWav').onclick=async()=>{const b=$('#renderWav');b.disabled=true;$('#exportDuration').disabled=true;$('#exportProgress').hidden=false;$('#exportProgress').value=0;$('#exportMessage').textContent='Preparing the soundfont and rendering…';$('#exportDownload').hidden=true;const [kind,val]=$('#exportDuration').value.split(':'),duration=kind==='bars'?Number(val)*4*60/project.tempo:Number(val);const snapshot=clone(project);try{const blob=await engine.export(snapshot,duration,p=>{$('#exportProgress').value=p;$('#exportMessage').textContent=`Rendering ${Math.round(p*100)}%`;});if(exportURL)URL.revokeObjectURL(exportURL);exportURL=URL.createObjectURL(blob);const a=$('#exportDownload');a.href=exportURL;a.download=fileName('Studio.wav');a.hidden=false;a.click();$('#exportMessage').textContent='Your WAV is ready. Download again below if needed.';toast('WAV export complete.');}catch(e){$('#exportMessage').textContent=e.message;toast('Export could not finish. Your project is safe.');}finally{b.disabled=false;$('#exportDuration').disabled=false;updateTransport();}};
function scope(){const canvas=$('#scope'),ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#64714533';ctx.lineWidth=1;ctx.beginPath();for(let x=0;x<w;x+=25){ctx.moveTo(x,0);ctx.lineTo(x,h);}ctx.moveTo(0,h/2);ctx.lineTo(w,h/2);ctx.stroke();ctx.strokeStyle=engine.ready?'#fbc16d':'#a68c53';ctx.lineWidth=1.8;ctx.shadowColor='#ffb842';ctx.shadowBlur=engine.ready?5:0;ctx.beginPath();const arr=new Float32Array(1024);if(engine.ready)engine.graph.analyser.getFloatTimeDomainData(arr);for(let i=0;i<w;i++){const y=h/2+(engine.ready?arr[Math.floor(i/w*1024)]*h*1.4:Math.sin(i*.035)*1.5);i?ctx.lineTo(i,y):ctx.moveTo(i,y);}ctx.stroke();ctx.shadowBlur=0;requestAnimationFrame(scope);}
$('#root').innerHTML=selection(NAMES.map((n,i)=>[i,n]),project.root);$('#scale').innerHTML=selection(Object.keys(SCALE).map(k=>[k,k[0].toUpperCase()+k.slice(1)]),project.scale);$('#preset').innerHTML='<option value="-1">Custom project</option>'+selection(PRESETS.map((p,i)=>[i,p.name]),PRESETS.findIndex(p=>p.name===project.title));
try{const r=await fetch('./assets/presets.json');if(!r.ok)throw Error('Sound list unavailable');presets=await r.json();}catch(e){toast('Could not load the instrument list. Reload this page.');presets=[{name:'Warm Synth',program:81,bank:0,drum:false},{name:'Standard kit',program:0,bank:0,drum:true}];}
renderAll();scope();
